// Python-compatible JSON helpers.
// dumps: mirrors json.dumps(obj, separators=(',', ':')) with the default
// ensure_ascii=True (all non-ASCII escaped as \uXXXX, lowercase hex,
// surrogate pairs for astral code points).

export function pyJsonDumpsString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '\b') {
      out += '\\b';
    } else if (ch === '\f') {
      out += '\\f';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (cp < 0x20) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else if (cp < 0x7f) {
      out += ch;
    } else if (cp <= 0xffff) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      // astral plane: encode as a UTF-16 surrogate pair
      const v = cp - 0x10000;
      const hi = 0xd800 + (v >> 10);
      const lo = 0xdc00 + (v & 0x3ff);
      out += '\\u' + hi.toString(16).padStart(4, '0');
      out += '\\u' + lo.toString(16).padStart(4, '0');
    }
  }
  return out + '"';
}

export function pyJsonDumps(obj) {
  if (obj === null || obj === undefined) return 'null';
  if (obj === true) return 'true';
  if (obj === false) return 'false';
  if (typeof obj === 'number') return String(obj);
  if (typeof obj === 'string') return pyJsonDumpsString(obj);
  if (Array.isArray(obj)) {
    return '[' + obj.map(pyJsonDumps).join(',') + ']';
  }
  // plain object: preserve insertion order like a Python dict
  const parts = [];
  for (const key of Object.keys(obj)) {
    parts.push(pyJsonDumpsString(key) + ':' + pyJsonDumps(obj[key]));
  }
  return '{' + parts.join(',') + '}';
}

export function pyJsonLoads(text) {
  return JSON.parse(text);
}

