// Python repr() emulation for the values this program prints:
// strings and flat dicts of strings, matching CPython's str.__repr__
// and dict.__repr__ output.

function isPrintable(cp) {
  // Approximation of Python's str.isprintable for the BMP control ranges.
  // Control characters and surrogates are not printable.
  if (cp < 0x20 || cp === 0x7f) return false;
  if (cp >= 0x80 && cp <= 0x9f) return false;
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return true;
}

export function pyReprString(s) {
  // CPython: use single quotes unless the string contains a single quote
  // and no double quote.
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) {
    quote = '"';
  }
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (!isPrintable(cp)) {
      if (cp <= 0xff) {
        out += '\\x' + cp.toString(16).padStart(2, '0');
      } else if (cp <= 0xffff) {
        out += '\\u' + cp.toString(16).padStart(4, '0');
      } else {
        out += '\\U' + cp.toString(16).padStart(8, '0');
      }
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyReprDict(obj) {
  const parts = [];
  for (const key of Object.keys(obj)) {
    parts.push(pyReprString(key) + ': ' + pyReprString(obj[key]));
  }
  return '{' + parts.join(', ') + '}';
}

