// Minimal re-implementation of the python-jose interfaces used here:
// jwt.encode (HS256), jwt.get_unverified_claims, jwt.get_unverified_header.

import { hmacSha256 } from './hmac.mjs';
import { base64urlEncode, base64urlDecode } from './base64url.mjs';
import { pyJsonDumps, pyJsonLoads } from './pyjson.mjs';

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function b64Json(obj) {
  return base64urlEncode(encoder.encode(pyJsonDumps(obj)));
}

export function encode(claims, key, algorithm = 'HS256') {
  if (algorithm !== 'HS256') {
    throw new Error('Unsupported algorithm: ' + algorithm);
  }
  const header = { alg: 'HS256', typ: 'JWT' };
  const signingInput = b64Json(header) + '.' + b64Json(claims);
  const signature = hmacSha256(encoder.encode(key), encoder.encode(signingInput));
  return signingInput + '.' + base64urlEncode(signature);
}

function unverifiedSegment(token, index, what) {
