// Minimal argparse-compatible parser for this program's CLI:
// two required string options, -h/--help, '--opt value' and '--opt=value'
// forms, and argparse-style error handling (usage on stderr, exit code 2).

export class ArgumentParser {
  constructor(prog, options) {
    // options: array of { name, metavar, help }
    this.prog = prog;
    this.options = options;
  }

  usage() {
    const parts = [`usage: ${this.prog} [-h]`];
    for (const opt of this.options) {
      parts.push(`--${opt.name} ${opt.metavar}`);
    }
    return parts.join(' ');
  }

  error(message) {
    process.stderr.write(this.usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(this.usage() + '\n\n');
    process.stdout.write('options:\n');
    process.stdout.write('  -h, --help         show this help message and exit\n');
    for (const opt of this.options) {
      process.stdout.write(`  --${opt.name} ${opt.metavar}\n`);
    }
  }

  parse(argv) {
    const result = {};
    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];
      if (arg === '-h' || arg === '--help') {
        this.printHelp();
        process.exit(0);
      }

      let name = null;
      let value = null;
      if (arg.startsWith('--')) {
        const eq = arg.indexOf('=');
        if (eq !== -1) {
          name = arg.slice(2, eq);
          value = arg.slice(eq + 1);
        } else {
          name = arg.slice(2);
        }
      }

      const opt = name !== null
        ? this.options.find((o) => o.name === name)
        : undefined;

      if (opt) {
        if (value === null) {
          if (i + 1 >= argv.length || argv[i + 1].startsWith('--')) {
            this.error(`argument --${opt.name}: expected one argument`);
          }
          value = argv[++i];
        }
        result[opt.name] = value;
        seen.add(opt.name);
      } else {
        extras.push(arg);
      }
    }

    const missing = this.options
      .filter((o) => !seen.has(o.name))
      .map((o) => '--' + o.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return result;
  }
}

