// Entry point mirroring test8.py:
// encode a JWT with HS256, then print the token, its unverified claims,
// and its unverified header using Python-compatible formatting.

import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { encode, getUnverifiedClaims, getUnverifiedHeader } from './lib/jwt.mjs';
import { pyReprDict } from './lib/pyrepr.mjs';

const parser = new ArgumentParser(basename(process.argv[1]), [
  { name: 'payload', metavar: 'PAYLOAD' },
  { name: 'secret', metavar: 'SECRET' },
]);
const args = parser.parse(process.argv.slice(2));

const secret = args.secret;
const payload = { data: args.payload };

// 创建token
const token = encode(payload, secret);
console.log(token);

// 获取未验证的claims（不验证签名）
const claims = getUnverifiedClaims(token);
console.log(pyReprDict(claims));

// 获取未验证的header
const header = getUnverifiedHeader(token);
console.log(pyReprDict(header));

